mapper.update:
UPDATE inbox_message
            SET status = 'PROCESSED', result_type = 'WORKFLOW_INSTANCE', result_id = #{workflowInstanceId},
                attempt_count = attempt_count + 1, last_error_code = NULL,
                last_attempt_at = #{now}, processed_at = #{now}, lock_version = lock_version + 1,
                updated_at = #{now}, updated_by_type = 'SERVICE', updated_by_id = NULL
            WHERE tenant_id = #{messageTenantId} AND inbox_id = #{inboxInboxId} AND status = 'RECOVERY_REQUIRED'
              AND producer_service = #{messageProducerService} AND message_id = #{messageMessageId} AND contract_ref = #{messageContractRef}
              AND contract_version = #{messageContractVersion} AND business_intent_key = #{messageBusinessIntentKey} AND body_sha256 = #{messageBodySha256}
              AND lock_version = #{inboxLockVersion}

UPDATE inbox_message
            SET status = 'REJECTED', attempt_count = attempt_count + 1,
                last_error_code = #{errorCode}, last_attempt_at = #{now}, processed_at = #{now},
                lock_version = lock_version + 1, updated_at = #{now},
                updated_by_type = 'SERVICE', updated_by_id = NULL
            WHERE tenant_id = #{messageTenantId} AND inbox_id = #{inboxInboxId} AND status = 'RECOVERY_REQUIRED'
              AND producer_service = #{messageProducerService} AND message_id = #{messageMessageId} AND contract_ref = #{messageContractRef}
              AND contract_version = #{messageContractVersion} AND business_intent_key = #{messageBusinessIntentKey} AND body_sha256 = #{messageBodySha256}
              AND lock_version = #{inboxLockVersion}

mapper.select:
SELECT workflow_instance_id, ticket_id, start_intent_key, definition_id,
       workflow_version_id, workflow_version_no, input_snapshot_sha256, condition_result
FROM workflow_instance WHERE tenant_id=#{tenantId}
AND ticket_id=#{value}
  AND start_intent_key=#{value}
FOR UPDATE
